// NewOverridePayload builds a dictionaries service override endpoint payload.
func NewOverridePayload(body *OverrideRequestBody, id int64, cookie string) *dictionaries.OverridePayload {
	v := &dictionaries.OverridePayload{
		BaseRevision: *body.BaseRevision,
		Reason:       *body.Reason,
	}
	v.Target = unmarshalConfigTargetRequestBodyToDictionariesConfigTarget(body.Target)
	v.Overrides = make([]*dictionaries.DictionaryOverride, len(body.Overrides))
	for i, val := range body.Overrides {
		if val == nil {
			v.Overrides[i] = nil
			continue
		}
		v.Overrides[i] = unmarshalDictionaryOverrideRequestBodyToDictionariesDictionaryOverride(val)
	}
	v.Extensions = make([]*dictionaries.DictionaryItem, len(body.Extensions))
	for i, val := range body.Extensions {
		if val == nil {
			v.Extensions[i] = nil
			continue
		}
		v.Extensions[i] = unmarshalDictionaryItemRequestBodyToDictionariesDictionaryItem(val)
	}
	v.ID = id
	v.Cookie = cookie

	return v
}

